					array('heading'=>'Katy production & custom builders (closeout programs)','content'=>'Multi-lot final-grade sod installs scheduled to the closing calendar across Katy ISD subdivisions and Cane Island filings — bonded, insured, and built around your superintendent\'s punch-list timeline.'),
					array('heading'=>'Katy HOAs & property management (common-area work)','content'=>'Entry monument restoration, median re-sod, amenity-center lawn work, and storm-recovery programs for Cinco Ranch, Cross Creek Ranch, Firethorne, Grand Lakes, and other Katy-area HOAs — with predictable scheduling and property-manager-friendly billing.'),
