				'residential' => array(
					array('heading'=>'Established Klein-area & Spring Trails homeowners','content'=>'Re-sod over aging or failing turf under mature Spring oak and pine canopy — shade-tolerant Palmetto St. Augustine over an amended surface, with selective canopy limb-up and surface-root pruning included as part of standard install scope.'),
					array('heading'=>'Augusta Pines & Gleannloch Farms premium homeowners','content'=>'Premium golf-community installs with HOA architectural-review documentation, Zeon Zoysia on pool-adjacent and signature front-yard zones, and Palmetto St. Augustine on shaded family-lawn areas. We have cleared review at both Augusta Pines and Gleannloch.'),
