				'commercial' => array(
					array('heading'=>'Klein ISD & Spring-area schools, athletic facilities, churches','content'=>'Laser-graded Tifway 419 Bermuda athletic fields with construction-grade base prep, irrigation coordination, grow-in protocols, and bid-document submittal packages. Plus sodded entries, courtyards, and visible-frontage work on Spring-area faith and education campuses.'),
					array('heading'=>'Spring commercial frontages & retail centers (FM 2920, I-45 corridor)','content'=>'Bondable commercial sod and hydroseed installs along the FM 2920 retail corridor and the I-45 north business district — typically hybrid sod-plus-hydroseed with premium sod across highway-visible frontage and engineered hydroseed across side and back zones.'),
