				'short_description_listing_view' => 'Aliana, Long Meadow Farms, and the Pecan Grove corridor make Richmond a hybrid-turf hotspot for us.',
				'short_description' => 'Aliana, Long Meadow Farms, and the Pecan Grove corridor make Richmond a hybrid-turf hotspot for us.',
				'tagline' => '"Sod where appearance matters most. Hydroseeding where scale matters most."',
				'installation_done' => '380+ installed · Since 2016',
