				'residential' => array(
					array('heading'=>'Established Tomball residential (Treeline, Pinecrest, Wildwood at Northpointe)','content'=>'Re-sod under mature pine and oak canopy with selective canopy limb-up, surface-root pruning, pH amendment, and shade-tolerant Palmetto St. Augustine over an organic-amended surface. The bulk of our suburban Tomball book.'),
					array('heading'=>'Rose Hill & rural Tomball custom builds','content'=>'Hybrid sod-plus-hydroseed plans on 1-acre to 5-acre Rose Hill and rural Tomball lots — premium sod near the home, pool, and outdoor entertaining zones; engineered Bermuda hydroseeding across outer acreage with organic amendment for moisture retention.'),
