				'we_install_in' => array(
					array('title'=>'Treeline','content'=>'Established Tomball residential with heavy mature pine and oak canopy. Palmetto St. Augustine dominates here over an organic-amended surface; the canopy limb-up and surface-root pruning work is the entire conversation before sod goes down. Bermuda fails reliably under Treeline canopy.'),
